DO $$ DECLARE c record; BEGIN
 FOR c IN SELECT conname FROM pg_constraint WHERE conrelid='penny_customer_records'::regclass AND contype='c' AND (pg_get_constraintdef(oid) LIKE '%status%' OR pg_get_constraintdef(oid) LIKE '%kind%') LOOP EXECUTE format('ALTER TABLE penny_customer_records DROP CONSTRAINT %I',c.conname); END LOOP;
END $$;
ALTER TABLE penny_customer_records ADD CONSTRAINT record_kind_pdf CHECK(kind IN ('TRAINING','CONTRACT','DEVELOPMENT','TECHNICAL','COMMERCIAL','INTERVENTION'));
ALTER TABLE penny_customer_records ADD CONSTRAINT record_status_pdf CHECK(status IN ('ACTIVE','EXPIRING','SUSPENDED','INSOLVENCY','EXPIRED','CANCELLED','PLANNED','IN_PROGRESS','COMPLETED','TO_ANALYZE','AWAITING_CONFIRMATION','DELIVERED','REQUESTED','APPROVED','COMPLETED_SALE','PENDING_APPROVAL','NOT_APPROVED','SCHEDULED','ON_HOLD','INTERRUPTED'));
ALTER TABLE penny_customer_records ADD COLUMN reference varchar(40);
CREATE UNIQUE INDEX penny_record_reference_unique ON penny_customer_records(reference) WHERE reference IS NOT NULL;
CREATE TABLE penny_intervention_counters(year integer PRIMARY KEY,last_number integer NOT NULL);
CREATE FUNCTION penny_intervention_reference() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE y int;n int; BEGIN IF NEW.kind='INTERVENTION' AND NEW.reference IS NULL THEN y=extract(year FROM coalesce((NEW.details->>'activityOn')::date,NEW.starts_on,current_date));INSERT INTO penny_intervention_counters VALUES(y,1) ON CONFLICT(year) DO UPDATE SET last_number=penny_intervention_counters.last_number+1 RETURNING last_number INTO n;NEW.reference=right(y::text,2)||'.RI.'||lpad(n::text,greatest(3,length(n::text)),'0');END IF;RETURN NEW;END $$;
CREATE TRIGGER intervention_reference BEFORE INSERT ON penny_customer_records FOR EACH ROW EXECUTE FUNCTION penny_intervention_reference();
CREATE TABLE penny_record_tasks(id bigserial PRIMARY KEY,record_id bigint NOT NULL REFERENCES penny_customer_records(id) ON DELETE RESTRICT,name varchar(200) NOT NULL,assignee_id bigint REFERENCES penny_users(id),progress integer NOT NULL DEFAULT 0 CHECK(progress BETWEEN 0 AND 100),starts_on date,ends_on date,CHECK(ends_on IS NULL OR starts_on IS NULL OR ends_on>=starts_on));
CREATE TABLE penny_record_interventions(record_id bigint NOT NULL REFERENCES penny_customer_records(id),intervention_id bigint NOT NULL REFERENCES penny_customer_records(id),PRIMARY KEY(record_id,intervention_id),CHECK(record_id<>intervention_id));
CREATE TABLE penny_contract_renewals(id bigserial PRIMARY KEY,record_id bigint NOT NULL REFERENCES penny_customer_records(id),previous_start date,previous_end date,new_start date NOT NULL,new_end date NOT NULL CHECK(new_end>=new_start),reason text NOT NULL,actor varchar(254) NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE penny_choices(id bigserial PRIMARY KEY,group_code varchar(60) NOT NULL,code varchar(120) NOT NULL,label varchar(200) NOT NULL,active boolean NOT NULL DEFAULT true,UNIQUE(group_code,code));
